export class ApiClient {
  private _authenticationService?: AuthenticationService;
  private _brandService?: BrandService;
  private _cartItemService?: CartItemService;
  private _cartService?: CartService;
  private _categoryService?: CategoryService;
  private _fileTransferService?: FileTransferService;
  private _orderItemService?: OrderItemService;
  private _orderService?: OrderService;
  private _paymentRefundService?: PaymentRefundService;
  private _paymentTransactionService?: PaymentTransactionService;
  private _productAttributeService?: ProductAttributeService;
  private _productAttributeValueService?: ProductAttributeValueService;
  private _productService?: ProductService;
  private _skuAttributeCombinationService?: SkuAttributeCombinationService;
  private _skuPriceService?: SkuPriceService;
  private _skuService?: SkuService;
  private readonly _transport: ClientTransport;
  private _userProfileService?: UserProfileService;

  constructor(transport: ClientTransport) {
    this._transport = transport;
  }

  get authenticationService(): AuthenticationService {
    return this._authenticationService ??= createAuthenticationServiceClient(this._transport);
  }

  get brandService(): BrandService {
    return this._brandService ??= createBrandServiceClient(this._transport);
  }

  get cartItemService(): CartItemService {
    return this._cartItemService ??= createCartItemServiceClient(this._transport);
  }

  get cartService(): CartService {
    return this._cartService ??= createCartServiceClient(this._transport);
  }

  get categoryService(): CategoryService {
    return this._categoryService ??= createCategoryServiceClient(this._transport);
  }

  get fileTransferService(): FileTransferService {
    return this._fileTransferService ??= createFileTransferServiceClient(this._transport);
  }

  get orderItemService(): OrderItemService {
    return this._orderItemService ??= createOrderItemServiceClient(this._transport);
  }

  get orderService(): OrderService {
    return this._orderService ??= createOrderServiceClient(this._transport);
  }

  get paymentRefundService(): PaymentRefundService {
    return this._paymentRefundService ??= createPaymentRefundServiceClient(this._transport);
  }

  get paymentTransactionService(): PaymentTransactionService {
    return this._paymentTransactionService ??= createPaymentTransactionServiceClient(this._transport);
  }

  get productAttributeService(): ProductAttributeService {
    return this._productAttributeService ??= createProductAttributeServiceClient(this._transport);
  }

  get productAttributeValueService(): ProductAttributeValueService {
    return this._productAttributeValueService ??= createProductAttributeValueServiceClient(this._transport);
  }

  get productService(): ProductService {
    return this._productService ??= createProductServiceClient(this._transport);
  }

  get skuAttributeCombinationService(): SkuAttributeCombinationService {
    return this._skuAttributeCombinationService ??= createSkuAttributeCombinationServiceClient(this._transport);
  }

  get skuPriceService(): SkuPriceService {
    return this._skuPriceService ??= createSkuPriceServiceClient(this._transport);
  }

  get skuService(): SkuService {
    return this._skuService ??= createSkuServiceClient(this._transport);
  }

  get userProfileService(): UserProfileService {
    return this._userProfileService ??= createUserProfileServiceClient(this._transport);
  }
}

export function createApiClient(transport: ClientTransport): ApiClient {
  return new ApiClient(transport);
}


